class Solution:
    def maxScore(self, n, k, x, arr):
        S = [0] * (n + 1)

        for L in range(1, n + 1):
            total = 0
            for start in range(n - L + 1):
                window = sorted(arr[start:start + L])
                median = window[(L - 1) // 2]
                total += median
            S[L] = total

        candidate = 0

        for b in range(31, -1, -1):
            new_candidate = candidate | (1 << b)
            count = 0
            for val in S[1:]:
                if (val & new_candidate) == new_candidate:
                    count += 1
            if count >= k:
                candidate = new_candidate

        return x | candidate
